cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');
// Search for the user more broadly
const users = db.prepare(\"SELECT * FROM users WHERE email LIKE '%sofia%' OR email LIKE '%ramirez%'\").all();
console.log(JSON.stringify(users, null, 2));
// Also check columns
const cols = db.prepare('PRAGMA table_info(users)').all();
console.log('Columns:', cols.map(c => c.name));
"

